nums = [int(v) for v in input().split()]
n = len(nums)
for i in range(n - 1):
    for j in range(n - 1 - i):
        if nums[j] > nums[j + 1]:
            nums[j], nums[j + 1] = nums[j + 1], nums[j]
print(' '.join(str(v) for v in nums))

scores = [int(v) for v in input().split()]
n = len(scores)
for i in range(n - 1):
    k = i
    for j in range(i + 1, n):
        if scores[j] > scores[k]:
            k = j
    scores[i], scores[k] = scores[k], scores[i]
print(' '.join(str(v) for v in scores))
